mapper.update:
update caregiver_invites
set status = 'expired',
    failure_reason = #{failureReason}
where token = #{token}
  and status = 'pending'

update caregiver_invites
set status = 'revoked',
    revoked_at = #{revokedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler},
    failure_reason = #{failureReason}
where token = #{token}
  and status = 'pending'
